def difference(X, d):
    # Calculate y = (X + d) mod 16
    y = (X + d) % 16
    # Calculate absolute difference
    return abs(X - y)

# Test all d in {-15, ..., 15} excluding 0
for d in range(-15, 16):
    if d == 0:
        continue

    found_X = False
    for X in range(16):
        diff = difference(X, d)
        if diff >= 2:
            # print(f"d={d}: Found X={X} yielding difference {diff}")
            found_X = True
            break

    if not found_X:
        print(f"FAILED for d={d}")
